def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Extract one field
        if i == len(line):
            # End of line
            if i == 0:
                # Empty line is one empty field
                fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == len(line):
                            # End of line is valid
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            # Comma follows
                            fields.append(field)
                            i += 1
                            break
                        else:
                            # Invalid: closing quote not followed by comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Invalid: unquoted field contains quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line):
                # Skip comma
                i += 1

    return fields

